let naviiReactionTimer=null;
function naviiReact(action='wave',which='about',silent=false){
 if(!['wave','flip','wink'].includes(action))action='wave';
 const fig=document.querySelector('[data-navii-figure="'+which+'"]');if(!fig)return;
 const reduce=window.matchMedia('(prefers-reduced-motion:reduce)').matches;
 fig.classList.remove('is-waving','is-flipping','is-winking','is-excited');void fig.offsetWidth;
 if(action==='wave')fig.classList.add('is-waving');
 if(action==='flip')fig.classList.add('is-flipping','is-excited');
 if(action==='wink')fig.classList.add('is-winking');
 if(which==='about'){
  const bubble=$('naviiSpeech');bubble.textContent=N(action+'Line');bubble.dataset.spoken=action;
  if(!reduce){bubble.classList.remove('pop');void bubble.offsetWidth;bubble.classList.add('pop')}
 }
 window.clearTimeout(fig._resetNavii);
 fig._resetNavii=setTimeout(()=>{fig.classList.remove('is-waving','is-flipping','is-winking','is-excited')},reduce?100:1450);
}
