const BLOOM_TEXTS={"ja": ["5 / 5 COMPLETE", "探究の花が咲いた！", "5つのステップを完了。ここまでの発見を大切にしよう", "探究に戻る", "もう一度見る", "花をもう一度見る"], "en": ["5 / 5 COMPLETE", "Your research is blooming!", "All five steps done. Take pride in what you discovered.", "Back to research", "Watch again", "Watch the flower bloom"], "ko": ["5 / 5 COMPLETE", "탐구의 꽃이 피었어요!", "다섯 단계를 완료했어요. 지금까지의 발견을 소중히 간직해요.", "탐구로 돌아가기", "다시 보기", "꽃 다시 보기"], "zh-CN": ["5 / 5 COMPLETE", "探究之花绽放了！", "五个步骤全部完成，珍惜一路发现的新知识", "返回探究", "再看一次", "再看一次花开"], "zh-TW": ["5 / 5 COMPLETE", "探究之花綻放了！", "五個步驟全部完成，珍惜一路發現的新知識", "返回探究", "再看一次", "再看一次花開"]};
let bloomPreviousFocus=null;
function ensureHandFonts(){
 const sources={'zh-CN':['xiaolaiHandStyles','https://fontsapi.zeoseven.com/281/main/result.css'],'zh-TW':['jasonHandStyles','https://fontsapi.zeoseven.com/251/main/result.css']};
 const f=sources[lang];if(f&&!document.getElementById(f[0])){const el=document.createElement('link');el.id=f[0];el.rel='stylesheet';el.href=f[1];document.head.appendChild(el)}
}
function syncBloomReplay(n){
 for(const id of ['bloomReplay','bloomReplayMobile']){const el=document.getElementById(id);if(el){el.hidden=n!==5;el.textContent='✿ '+BLOOM_TEXTS[lang][5]}}
}
function syncBloomWords(){const l=BLOOM_TEXTS[lang]||BLOOM_TEXTS.ja;['bloomKicker','bloomTitle','bloomDesc','bloomClose','bloomAgain'].forEach((id,i)=>{const el=document.getElementById(id);if(el)el.textContent=l[i]});syncBloomReplay(data.done.filter(Boolean).length);ensureHandFonts()}
function bloomDust(){const box=document.getElementById('bloomDustField');if(box.childElementCount)return;const colors=['#edb3b1','#e9c67c','#a5cdb5','#d6c7e8','#efdbc9'];for(let i=0;i<44;i++){const dot=document.createElement('span');dot.className='bloom-dust';let f=x=>((x*137+29)%101)/101;dot.style.cssText=`--x:${(4+f(i+1)*93).toFixed(1)}%;--y:${(12+f(i+30)*78).toFixed(1)}%;--sz:${(3+f(i+11)*7).toFixed(1)}px;--c:${colors[i%colors.length]};--dur:${(2.6+f(i+17)*2.8).toFixed(1)}s;--wait:${(f(i+51)*3.3).toFixed(1)}s;--dx:${((f(i+7)-.5)*110).toFixed(1)}px`;box.appendChild(dot)}}
function grandPetalParticles(){
 const field=document.getElementById('grandConfetti');if(!field||field.childElementCount)return;
 const reduced=window.matchMedia('(prefers-reduced-motion:reduce)').matches;if(reduced)return;
 for(let i=0;i<34;i++){
  const x=(i*43+17)%100, y= -((i*11)%75)-7;
  const p=document.createElement('span');p.className='grand-falling-petal';
  p.style.cssText=`--x:${x}%;--y:${y}%;--w:${6+i%5*1.8}px;--angle:${i*27}deg;--dur:${6.5+(i%7)*.7}s;--wait:${2.35+(i%13)*.28}s;--sway:${((i%2)?1:-1)*(32+i%7*18)}px`;
  field.appendChild(p);
 }
}
function resetBloomAnimation(){
 const old=document.getElementById('bloomOverlay');
 old.classList.remove('grand-play');void old.offsetWidth;old.classList.add('grand-play');
}
function showBloom(){syncBloomWords();bloomPreviousFocus=document.activeElement;const el=$('bloomOverlay');el.hidden=false;document.body.classList.add('bloom-open');if(!window.matchMedia('(prefers-reduced-motion:reduce)').matches){bloomDust();grandPetalParticles()}resetBloomAnimation();$('bloomClose').focus()}
function closeBloom(){$('bloomOverlay').hidden=true;document.body.classList.remove('bloom-open');if(bloomPreviousFocus&&bloomPreviousFocus.isConnected)bloomPreviousFocus.focus()}
function replayBloom(){
 const el=$('bloomOverlay');el.hidden=true;
 const parts=el.querySelectorAll('.grand-petal,.grand-leaf,.grand-stem,.grand-core,.grand-small-flower,.grand-sprigs,.grand-starburst,.grand-halo,.grand-stem-highlight,.bloom-ui,.grand-aura,.grand-horizon,.bloom-veil');
 parts.forEach(x=>{x.style.animation='none'});
 void el.offsetWidth;el.hidden=false;
 parts.forEach(x=>x.style.removeProperty('animation'));
 resetBloomAnimation();$('bloomClose').focus()
}
// Only show this guide to a newcomer, and never require a blocking tour.
const PROGRESS_GUIDE_KEY='tankyu-navi-progress-hint-v1';
const PROGRESS_GUIDE_TEXT={
 ja:['↗ 進捗はここからチェック','終わったステップは「完了にする」を押してね','わかった'],
 en:['↗ Check your progress here','Finished a step? Select “Mark complete” below','Got it'],
 ko:['↗ 여기서 진행 상황 체크','단계를 마쳤다면 아래의 ‘완료’ 버튼을 눌러주세요','알겠어요'],
 'zh-CN':['↗ 在这里勾选进度','完成步骤后，点击下面的“标记完成”','知道了'],
 'zh-TW':['↗ 在這裡勾選進度','完成步驟後，點選下方的「標記完成」','知道了']};
let progressGuideDismissed=false;
try{progressGuideDismissed=localStorage.getItem(PROGRESS_GUIDE_KEY)==='yes'}catch{}
function updateProgressGuide(){
 const show=!progressGuideDismissed&&!data.done.some(Boolean);
 const words=PROGRESS_GUIDE_TEXT[lang]||PROGRESS_GUIDE_TEXT.ja;
 $('progressGuideHome').hidden=!show;
 $('progressGuideStep').hidden=!show;
 $('progressGuideHome').textContent=words[0];
 $('progressGuideMessage').textContent=words[1];
 $('progressGuideDismiss').textContent=words[2];
}
function dismissProgressGuide(){
 progressGuideDismissed=true;
 try{localStorage.setItem(PROGRESS_GUIDE_KEY,'yes')}catch{}
 updateProgressGuide();
}
$('progressGuideHome').addEventListener('click',()=>{
 setPage('steps');
 requestAnimationFrame(()=>{
  const guide=$('progressGuideStep');
  if(!guide.hidden)guide.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});
 });
});
$('progressGuideDismiss').addEventListener('click',dismissProgressGuide);
for(const id of ['bloomReplay','bloomReplayMobile'])$(id)?.addEventListener('click',showBloom);
$('bloomClose').addEventListener('click',closeBloom);$('bloomExit').addEventListener('click',closeBloom);$('bloomAgain').addEventListener('click',replayBloom);
document.addEventListener('keydown',e=>{if(!$('bloomOverlay').hidden){if(e.key==='Escape')closeBloom();if(e.key==='Tab'){const els=[$('bloomExit'),$('bloomClose'),$('bloomAgain')];const i=els.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();els[2].focus()}else if(!e.shiftKey&&i===2){e.preventDefault();els[0].focus()}}}});
document.getElementById('languageSelect').addEventListener('change',()=>{requestAnimationFrame(syncBloomWords)});
document.addEventListener('click',e=>{const goto=e.target.closest('[data-goto],[data-nav]');if(goto){setPage(goto.dataset.goto||goto.dataset.nav);return}const step=e.target.closest('[data-done]');if(step){let i=Number(step.dataset.done);const wasComplete=data.done.every(Boolean);data.done[i]=!data.done[i];if(data.done[i])dismissProgressGuide();save();renderHome();renderPlant();if(!wasComplete&&data.done.every(Boolean))showBloom();return}const edit=e.target.closest('[data-note-edit]');if(edit){const n=data.notes.find(n=>String(n.id)===edit.dataset.noteEdit);if(n){setNoteForm(n);setPage('notes');$('noteTitle').focus()}return}const del=e.target.closest('[data-note-delete]');if(del){const note=data.notes.find(n=>String(n.id)===del.dataset.noteDelete);if(note&&confirm(T('このノートを削除しますか？'))){data.notes=data.notes.filter(n=>String(n.id)!==del.dataset.noteDelete);save();renderNotes();renderAdvice();toast(T('ノートを削除しました'))}return}const task=e.target.closest('[data-task-remove]');if(task){data.tasks=data.tasks.filter(t=>t.id!==task.dataset.taskRemove);save();renderTasks();return}const add=e.target.closest('[data-add-task]');if(add){addTask(add.dataset.addTask);return}});
document.addEventListener('change',e=>{const c=e.target.closest('[data-check]');if(c){data.checks[Number(c.dataset.check)]=c.checked;save();renderChecks();return}const task=e.target.closest('[data-task-toggle]');if(task){const t=data.tasks.find(x=>x.id===task.dataset.taskToggle);if(t){t.done=task.checked;save();renderTasks();if(t.done)toast(T('ひとつ完了！'))}}});

for(const id of ['topic','purpose','known','unknown']){ $(id).value=data.project[id]||'';$(id).addEventListener('input',()=>{data.project[id]=$(id).value;save();renderHome();renderAdvice()})}
